1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Scenario = {
12	  customer: Customer;
13	  steps: { op: string; items: Item[] }[];
14	};
15	
16	export type ScenarioResult = {
17	  results: { premium: number }[];
18	};
19	
20	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	  rune: 25,
26	  moonstone: 25,
27	};
28	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
29	const CURSE_SURCHARGE_PERCENT = 50;
30	const HIGH_ENCHANTMENT_THRESHOLD = 5;
31	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
32	const LOYALTY_THRESHOLD_YEARS = 2;
33	const LOYALTY_DISCOUNT_PERCENT = 20;
34	const PROCESSING_FEE = 5;
35	
36	const percentOf = (amount: number, percent: number): number =>
37	  (amount * percent) / 100;
38	
39	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
40	
41	const BLOCK_SIZE = 3;
42	const BLOCK_BASE_PREMIUM = 60;
43	
44	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
45	const countAlikeItems = (items: Item[]): Map<string, number> =>
46	  items.reduce(
47	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
48	    new Map<string, number>(),
49	  );
50	
51	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
52	
53	const basePremiumForAlikeItems = (type: string, count: number): number =>
54	  formsBuildingBlock(count)
55	    ? BLOCK_BASE_PREMIUM
56	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
57	
58	const policyBasePremium = (items: Item[]): number =>
59	  [...countAlikeItems(items)].reduce(
60	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
61	    0,
62	  );
63	
64	const itemBasePremium = (item: Item): number =>
65	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
66	
67	const isHighlyEnchanted = (item: Item): boolean =>
68	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
69	
70	/** Item-specific surcharges stack additively. */
71	const itemSurchargePercent = (item: Item): number =>
72	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
73	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
74	
75	/**
76	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
77	 * premium — unlike policy-wide modifiers, which apply to the policy base.
78	 */
79	const totalItemSurcharges = (items: Item[]): number =>
80	  items.reduce(
81	    (total, item) =>
82	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
83	    0,
84	  );
85	
86	const isLongStanding = (customer: Customer): boolean =>
87	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
88	
89	/**
90	 * The net of all policy-wide percentages. Policy-wide modifiers are
91	 * percentages of the POLICY base premium — unlike item-specific modifiers,
92	 * which apply to the affected item's own base. The net is negative when the
93	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
94	 */
95	const netPolicyAdjustmentPercent = (customer: Customer): number =>
96	  FIRST_INSURANCE_SURCHARGE_PERCENT -
97	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0);
98	
99	const policyAdjustment = (policyBase: number, customer: Customer): number =>
100	  percentOf(policyBase, netPolicyAdjustmentPercent(customer));
101	
102	const quotePremium = (items: Item[], customer: Customer): number => {
103	  const basePremium = policyBasePremium(items);
104	  return roundInMHPCOsFavour(
105	    basePremium +
106	      totalItemSurcharges(items) +
107	      policyAdjustment(basePremium, customer) +
108	      PROCESSING_FEE,
109	  );
110	};
111	
112	export const runScenario = (scenario: Scenario): ScenarioResult => ({
113	  results: scenario.steps.map((step) => ({
114	    premium: quotePremium(step.items, scenario.customer),
115	  })),
116	});
